29	 * Private Types
30	 ****************************************************************************/
31	
32	typedef struct
33	{
34	  float x, y;
35	  float vx, vy;
36	  float radius;
37	  lv_color_t color;
38	  lv_obj_t *trail[TRAIL_LENGTH];
39	  lv_obj_t *ball;
40	  float trail_x[TRAIL_LENGTH];
41	  float trail_y[TRAIL_LENGTH];
42	} ball_t;
43	
44	typedef struct
45	{
46	  lv_obj_t *screen;
47	  lv_obj_t *canvas;
48	  ball_t balls[NUM_BALLS];
49	  lv_obj_t *title_label;
50	  lv_obj_t *fps_label;
51	  lv_obj_t *wave_canvas;
52	  uint32_t frame_count;
53	  uint32_t last_tick;
54	  float wave_phase;
55	  lv_anim_t title_anim;
56	  lv_anim_t pulse_anim;
57	} animation_ctx_t;
58	
59	/****************************************************************************
60	 * Private Data
61	 ****************************************************************************/
62	
63	static animation_ctx_t g_anim;
64	
65	/* Color palette - vibrant neon colors */
66	
67	static const uint32_t g_palette[NUM_BALLS] =
68	{
69	  0xFF6B6B, 0x4ECDC4, 0x45B7D1, 0x96CEB4,
70	  0xFFEAA7, 0xDDA0DD, 0x98D8C8, 0xF7DC6F,
71	  0xBB8FCE, 0x85C1E9, 0xF8C471, 0x82E0AA
72	};
73	
74	/****************************************************************************
75	 * Private Functions
76	 ****************************************************************************/
77	
78	static float randf(float min, float max)
79	{
80	  return min + (float)rand() / RAND_MAX * (max - min);
81	}
82	
83	static void init_balls(void)
84	{
85	  int i, j;
86	  lv_obj_t *parent = lv_screen_active();
87	  int sw = lv_display_get_horizontal_resolution(NULL);
88	  int sh = lv_display_get_vertical_resolution(NULL);
89	
90	  for (i = 0; i < NUM_BALLS; i++)
91	    {
92	      g_anim.balls[i].radius = 15.0f + randf(0, 20);
93	      g_anim.balls[i].x = randf(g_anim.balls[i].radius,
94	                                 sw - g_anim.balls[i].radius);
95	      g_anim.balls[i].y = randf(g_anim.balls[i].radius,
96	                                 sh - g_anim.balls[i].radius);
97	      g_anim.balls[i].vx = randf(1.5f, 4.0f) * (rand() % 2 ? 1 : -1);
98	      g_anim.balls[i].vy = randf(1.5f, 4.0f) * (rand() % 2 ? 1 : -1);
99	      g_anim.balls[i].color = lv_color_hex(g_palette[i]);
100	
101	      /* Create trail circles */
102	
103	      for (j = 0; j < TRAIL_LENGTH; j++)
104	        {
105	          lv_obj_t *t = lv_obj_create(parent);
106	          lv_obj_remove_style_all(t);
