108	                          j * 0.12f)),
109	                          (int)(g_anim.balls[i].radius * 2 * (1.0f -
110	                          j * 0.12f)));
111	          lv_obj_set_style_radius(t, LV_RADIUS_CIRCLE, 0);
112	          lv_obj_set_style_bg_color(t, g_anim.balls[i].color, 0);
113	          lv_obj_set_style_bg_opa(t, LV_OPA_100 - j * 15, 0);
114	          lv_obj_set_pos(t, (int)g_anim.balls[i].x,
